using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation/generated values
        // that change per evaluation. Use a fixed seed value instead of DateTime.UtcNow.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosAppDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "SampleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Vehicle>(b =>
        {
            b.ToContainer("Vehicles");
            b.HasPartitionKey(v => v.PartitionKey);
            b.HasNoDiscriminator();

            // EF Core 9 breaking change: The Cosmos provider now uses "$type" instead of
            // "Discriminator" for the discriminator property by default.
            // For existing documents that already have "Discriminator", override explicitly:
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Vehicle
{
    public string Id { get; set; } = null!;
    public string PartitionKey { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// EF Core 9 breaking change: Synchronous I/O is no longer supported by the Cosmos provider.
// All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).
class CosmosQueryService
{
    private readonly CosmosAppDbContext _db;

    public CosmosQueryService(CosmosAppDbContext db) => _db = db;

    // BEFORE (EF Core 8 — sync, now throws InvalidOperationException in EF Core 9):
    // public List<Vehicle> GetAll() => _db.Vehicles.ToList();

    // AFTER (EF Core 9 — must use async):
    public async Task<List<Vehicle>> GetAllAsync() =>
        await _db.Vehicles.ToListAsync();

    public async Task AddAsync(Vehicle v)
    {
        _db.Vehicles.Add(v);
        await _db.SaveChangesAsync();
    }
}

